  "structures/double_linked_list.py::Double_Linked_List.append": "def append(self, val):\n    \"\"\"В конец. Время O(1) — благодаря tail. Память O(1) — один новый узел.\"\"\"\n    new_node = Node(val)\n    self.size += 1\n    if not self.head:\n        self.head = self.tail = new_node\n        return\n    self.tail.next = new_node\n    new_node.prev = self.tail\n    self.tail = new_node",
  "structures/double_linked_list.py::Double_Linked_List.appendleft": "def appendleft(self, val):\n    \"\"\"В начало. Время O(1), память O(1) — один новый узел.\"\"\"\n    new_node = Node(val)\n    self.size += 1\n    if not self.head:\n        self.head = self.tail = new_node\n        return\n    self.head.prev = new_node\n    new_node.next = self.head\n    self.head = new_node",
  "structures/double_linked_list.py::Double_Linked_List.pop": "def pop(self, idx=-1):\n    \"\"\"Удалить по индексу (по умолчанию последний) и вернуть значение.\n    Время: с конца/начала — O(1), из середины — O(n). Память O(1) — только указатели.\"\"\"\n    if self.size == 0:\n        raise IndexError(\"pop from empty list\")\n    node = self._get_node(idx)\n    prev_node, next_node = node.prev, node.next\n    if prev_node:\n        prev_node.next = next_node\n    else:                      # удалили голову\n        self.head = next_node\n    if next_node:\n        next_node.prev = prev_node\n    else:                      # удалили хвост\n        self.tail = prev_node\n    self.size -= 1\n    return node.val",
  "structures/double_linked_list.py::Double_Linked_List.insert": "def insert(self, idx, val):\n    if idx < 0:\n        idx += self.size\n    idx = max(0, min(idx, self.size))\n    if idx == 0:\n        return self.appendleft(val)\n    if idx == self.size:\n        return self.append(val)\n    new_node = Node(val)\n    prev_node = self._get_node(idx - 1)\n    next_node = prev_node.next\n    new_node.prev, new_node.next = prev_node, next_node\n    prev_node.next = new_node\n    next_node.prev = new_node\n    self.size += 1",
  "structures/double_linked_list.py::Double_Linked_List.remove": "def remove(self, val):\n    cur = self.head\n    while cur:\n        if cur.val == val:\n            if cur.prev:\n                cur.prev.next = cur.next\n            else:\n                self.head = cur.next\n            if cur.next:\n                cur.next.prev = cur.prev\n            else:\n                self.tail = cur.prev\n            self.size -= 1\n            return\n        cur = cur.next\n    raise ValueError(f\"{val} not in list\")",
  "structures/double_linked_list.py::Double_Linked_List.reverse": "def reverse(self):\n    \"\"\"Меняем местами prev и next у каждого узла.\n    Время O(n) — один проход, память O(1) — разворот на месте.\"\"\"\n    cur = self.head\n    while cur:\n        cur.prev, cur.next = cur.next, cur.prev\n        cur = cur.prev                 # бывший next\n    self.head, self.tail = self.tail, self.head",
  "structures/double_linked_list.py::Double_Linked_List.__iter__": "def __iter__(self):\n    cur = self.head\n    while cur:\n        yield cur.val\n        cur = cur.next",
