  "teacher/Hash_table.py::Hashtable._hash": "def _hash(self, key):\n    if isinstance(key, str):\n        data = key.encode('utf-8')\n    else:\n        data = str(key).encode('utf-8')\n    \n    hash_val = 0x811c9dc5 \n    for byte in data:\n        hash_val ^= byte\n        hash_val *= 0x01000193  \n        hash_val &= 0xFFFFFFFF  \n    \n    return hash_val % self.capacity",
  "teacher/Hash_table.py::Hashtable._load_factor": "def _load_factor(self):\n    return self.size / self.capacity",
  "teacher/Hash_table.py::Hashtable._resize": "def _resize(self):\n    old_buckets = self.buckets\n    self.capacity *= 2\n    self.buckets = [None] * self.capacity\n    self.size = 0\n    for node in old_buckets:\n        while node:\n            self[node.key] = node.val\n            node = node.next",
  "teacher/Hash_table.py::Hashtable.__setitem__": "def __setitem__(self, key, val):\n    if self._load_factor() >= self.load_factor:\n        self._resize()\n    head = self.buckets[self._hash(key)]\n    if head is None:\n        self.buckets[self._hash(key)] = Node(key, val)\n        self.size += 1\n        return\n\n    while head:\n        if head.key == key:\n            head.val = val\n            return\n        prev = head\n        head = head.next\n    prev.next = Node(key, val)\n    self.size += 1",
