  "teacher/Linked_list.py::Linked_list": "class Linked_list:\n    def __init__(self, *lst):\n        self.size = len(lst)\n        if not lst:\n            self.head = None\n            return\n        self.head = Node(lst[0])\n        cur = self.head\n        for i in range(1, len(lst)):\n            cur.next = Node(lst[i])\n            cur = cur.next\n\n    def __str__(self):\n        if not self.head:\n            return 'empty'\n        a = ''\n        cur = self.head\n        while cur:\n            if not cur.next:\n                a += f'{cur.val}'\n                return a\n            a += f'{cur.val}->'\n            cur = cur.next\n\n    def __len__(self):\n        return self.size\n\n    def is_empty(self):\n        return self.head is None\n\n    def _get_item(self, idx):\n        if idx < 0 or idx >= self.size:\n            raise IndexError(\"Index out of range\")\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx:\n            cur = cur.next\n            cur_idx += 1\n        return cur\n\n    def __getitem__(self, idx):\n        target = self._get_item(idx)\n        return target.val\n\n    def append(self, val):\n        new_node = Node(val)\n        if self.head is None:\n            self.head = new_node\n        else:\n            cur = self.head\n            while cur.next:\n                cur = cur.next\n            cur.next = new_node\n        self.size += 1\n\n    def insert(self, idx, val):\n        if idx < 0 or idx > self.size:\n            raise IndexError(\"Index out of range\")\n\n        new_node = Node(val)\n\n        if idx == 0:\n            new_node.next = self.head\n            self.head = new_node\n        else:\n            prev = self._get_item(idx - 1)\n            new_node.next = prev.next\n            prev.next = new_node\n\n        self.size += 1\n\n    def remove(self, val):\n        if self.head is None:\n            raise ValueError(\"Value not found\")\n\n        if self.head.val == val:\n            self.head = self.head.next\n            self.size -= 1\n            return\n\n        cur = self.head\n        while cur.next is not None and cur.next.val != val:\n            cur = cur.next\n\n        if cur.next is None:\n            raise ValueError(\"Value not found\")\n\n        cur.next = cur.next.next\n        self.size -= 1\n\n    def pop(self, idx):\n        if idx < 0:\n            raise IndexError(\"Negative index is not allowed\")\n        if idx >= self.size:\n            raise IndexError(\"Index out of range\")\n\n        if idx == 0:\n            target = self.head\n            self.head = self.head.next\n            self.size -= 1\n            return target.val\n\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx - 1:\n            cur = cur.next\n            cur_idx += 1\n\n        target = cur.next\n        cur.next = target.next\n        self.size -= 1\n        return target.val\n\n    def swap(self, idx1, idx2):\n        node1 = self._get_item(idx1)\n        node2 = self._get_item(idx2)\n        node1.val, node2.val = node2.val, node1.val\n\n    def reverse(self):\n        prev = None\n        cur = self.head\n        while cur:\n            nxt = cur.next\n            cur.next = prev\n            prev = cur\n            cur = nxt\n        self.head = prev\n\n    def __setitem__(self, idx, value):\n        target = self._get_item(idx)\n        target.val = value\n\n    def __iter__(self):\n        cur = self.head\n        while cur:\n            yield cur.val\n            cur = cur.next",
